def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def get_point(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            x = value[0]
            y = value[1]
            if isinstance(x, int) and isinstance(y, int):
                return x, y
        return default

    def nearest(points, sx, sy):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                x, y = p[0], p[1]
                if isinstance(x, int) and isinstance(y, int):
                    d = abs(x - sx) + abs(y - sy)
                    if best_d is None or d < best_d:
                        best = (x, y)
                        best_d = d
        return best

    def farthest(points, sx, sy):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                x, y = p[0], p[1]
                if isinstance(x, int) and isinstance(y, int):
                    d = abs(x - sx) + abs(y - sy)
                    if best_d is None or d > best_d:
                        best = (x, y)
                        best_d = d
        return best

    def step_toward(ax, ay, bx, by):
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(ax, ay, bx, by):
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_point(observation.get("self_position"), (0, 0))
    ox, oy = get_point(observation.get("opponent_position"), (sx, sy))
    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
